// HT-36 T01 - Valida el token de sesion (contrato C1).
//
// El token lo emite el login de Central (nodo "Generar token"):
//   base64url(payload) + "." + HMAC-SHA256 en hex del primer tramo, con
//   N8N_AUTH_SECRET; payload { sub, id, role, iat, exp } con exp en ms.
// Salida: { valido: true, usuario_id, rol, exp (segundos) } o
//         { valido: false, http_code: 401 | 403 | 500, error }.
// Quien llama responde el error al cliente con ese codigo.
const crypto = require('crypto');

// Transicion: mientras la app no envie el token (HT-36 T03, TE_ENVIAR_TOKEN),
// los webhooks que ya existian (reports-list, reports-history, report-resolve)
// llaman con permitir_sin_token=true: una peticion SIN cabecera sigue como
// antes y el webhook usa el usuario que manda el cuerpo. Con cabecera se
// valida siempre. Los webhooks nuevos no lo pasan y exigen el token.
// Pasar EXIGIR_TOKEN a true cuando TE_ENVIAR_TOKEN este activo en produccion.
const EXIGIR_TOKEN = false;

const NIVEL = { ciudadano: 1, operador: 2 };
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const entrada = $input.first().json;
// Un rol_minimo desconocido exige lo maximo: nunca abre una ruta por error.
const rolMinimo = NIVEL[entrada.rol_minimo] ? entrada.rol_minimo : 'operador';
const cabecera = String(entrada.authorization || '').trim();
const rechazar = (http_code, error) => [{ json: { valido: false, http_code, error } }];

const permitirSinToken = entrada.permitir_sin_token === true || entrada.permitir_sin_token === 'true';

if (!cabecera) {
  if (EXIGIR_TOKEN || !permitirSinToken) return rechazar(401, 'token_invalido');
  return [{ json: { valido: true, sin_token: true, usuario_id: null, rol: null, exp: null } }];
}

const partes = cabecera.match(/^Bearer\s+([A-Za-z0-9_-]+)\.([0-9a-f]{64})$/i);
if (!partes) return rechazar(401, 'token_invalido');

let secreto = null;
try {
  secreto = $env.N8N_AUTH_SECRET || null;
} catch (e) {
  secreto = null;
}
if (!secreto) return rechazar(500, 'autenticacion_no_configurada');

// Comparacion en tiempo constante, sobre bytes del mismo largo.
const esperada = Buffer.from(crypto.createHmac('sha256', secreto).update(partes[1]).digest('hex'), 'hex');
const recibida = Buffer.from(partes[2].toLowerCase(), 'hex');
if (esperada.length !== recibida.length || !crypto.timingSafeEqual(esperada, recibida)) {
  return rechazar(401, 'token_invalido');
}

let payload;
try {
  payload = JSON.parse(Buffer.from(partes[1], 'base64url').toString('utf8'));
} catch (e) {
  return rechazar(401, 'token_invalido');
}

const expMs = Number(payload.exp);
if (!Number.isFinite(expMs) || expMs <= Date.now()) return rechazar(401, 'token_invalido');
if (!UUID.test(String(payload.id || ''))) return rechazar(401, 'token_invalido');
if (!NIVEL[payload.role]) return rechazar(401, 'token_invalido');
if (NIVEL[payload.role] < NIVEL[rolMinimo]) return rechazar(403, 'rol_no_permitido');

return [{
  json: {
    valido: true,
    sin_token: false,
    usuario_id: payload.id,
    rol: payload.role,
    exp: Math.floor(expMs / 1000),
  },
}];
